-- 将 About 文案写入数据库，首页与详情页使用独立内容
INSERT INTO settings (key, value, type, description) VALUES
  ('about_author_bio_short', '全栈与 AI 应用工程师，专注于将图形引擎、智能工作流与模型能力转化为可落地的产品，当前聚焦虚拟试穿、智能搭配与服装自动打版。', 'string', '首页作者简介'),
  ('about_author_bio', '我是一名专注于复杂产品与 AI 系统落地的全栈工程师。我的工作不止于完成界面或接口，而是将图形交互、业务架构、数据链路、模型推理与智能体编排整合为可持续演进的产品能力。从专业图形工具、医疗 AI 到企业智能工作流与服装科技，我始终关注同一件事：如何把复杂技术真正变成可使用、可复用、可规模化的系统。', 'string', '作者简介（个人定位）'),
  ('about_author_bio_2', '我曾参与在线 CAD 编辑器的核心研发，基于 Vue 3、Three.js、NestJS 与 MongoDB 构建浏览器端图形编辑与数据服务。在医疗 AI 领域，参与搭建从扫码问卷、病历与影像资料上传，到语义解析、临床信息结构化和自研模型推理的完整链路，自动归纳现病史、既往史与主诉等内容，为医生提供诊疗决策的辅助参考。这些经历让我对复杂交互、专业数据与 AI 工程之间的衔接有了完整认识。', 'string', '作者简介（行业项目）'),
  ('about_author_bio_3', '在桌面办公产品中，我负责过工作流平台建设，在 n8n 基础上进行深度定制，统一集成内外部工具、MCP、Agent 与各类业务服务；同时将可复用流程封装为 API 与 MCP 能力，供公司其他系统调用，并完成与桌面端的端到端打通。目前，我正在推进 AI 与服装产业的深度融合，聚焦虚拟试穿、智能搭配与服装自动打版，探索从二维纸样、三维表达到生成式智能的新一代服装研发工具链。', 'string', '作者简介（工作流与当前方向）'),
  ('about_author_bio_4', '除行业项目外，我也持续用完整作品验证对产品、AI 与交互设计的理解。《墨灵 Moling》是一套面向长篇小说创作的桌面 AI 工作台，将故事规划、章节生产、Canon 记忆、审稿与修订组织为可追踪的创作闭环；《遗忘潮汐 The Forgetting Tide》则是一个从世界观、角色与核心玩法，到产品界面、场景美术与原创配乐的完整叙事构筑游戏案例。它们代表了我对“从概念到可运行产品”的长期坚持。', 'string', '作者简介（代表作品）')
ON CONFLICT (key) DO UPDATE
SET value = EXCLUDED.value,
    type = EXCLUDED.type,
    description = EXCLUDED.description,
    updated_at = CURRENT_TIMESTAMP;
